"""ITRS <-> Observed (AltAz/HADec) transformations.

This module implements direct transformations between ITRS and the observed
frames (AltAz and HADec) without leaving the terrestrial frame.

The main motivation is to support transformations for nearby objects (e.g.,
satellites) in a way that is purely geometric/topocentric.  In particular, the
transformations here treat ITRS positions as time-invariant and thus do not
attempt to synchronize ``obstime`` between the input coordinate and the output
frame.

Refraction is supported using the same two-constant model as ERFA.
"""

import numpy as np
import erfa

from astropy import units as u
from astropy.coordinates.baseframe import frame_transform_graph
from astropy.coordinates.transformations import FunctionTransformWithFiniteDifference
from astropy.coordinates.matrix_utilities import rotation_matrix, matrix_transpose
from astropy.coordinates.representation import (
    SphericalRepresentation,
    UnitSphericalRepresentation,
)

from .altaz import AltAz
from .hadec import HADec
from .itrs import ITRS
from .utils import PIOVER2


def _get_lon_lat(location):
    lon, lat, _ = location.to_geodetic('WGS84')
    return lon.to_value(u.radian), lat.to_value(u.radian)


def _itrs_to_altaz_mat(location):
    """Rotation matrix from ITRS to AltAz cartesian axes."""
    elong, elat = _get_lon_lat(location)

    # AltAz is left-handed.
    minus_x = np.eye(3)
    minus_x[0, 0] = -1.0

    return (
        minus_x
        @ rotation_matrix(PIOVER2 - elat, 'y', unit=u.radian)
        @ rotation_matrix(elong, 'z', unit=u.radian)
    )


def _itrs_to_hadec_mat(location):
    """Rotation matrix from ITRS to HADec cartesian axes."""
    elong, _ = _get_lon_lat(location)

    # HADec is left-handed.
    minus_y = np.eye(3)
    minus_y[1, 1] = -1.0

    return minus_y @ rotation_matrix(elong, 'z', unit=u.radian)


def _itrs_to_observed_mat(observed_frame):
    if observed_frame.location is None:
        raise ValueError("Observed frame has no location; cannot transform from/to ITRS")

    if isinstance(observed_frame, AltAz):
        return _itrs_to_altaz_mat(observed_frame.location)
    elif isinstance(observed_frame, HADec):
        return _itrs_to_hadec_mat(observed_frame.location)
    else:
        raise TypeError(
            "_itrs_to_observed_mat only supports AltAz and HADec frames"
        )


def _refraction_constants(observed_frame):
    """Refraction constants (A, B) for ERFA's two-constant model."""
    # Use the same approach as in erfa_astrom.ErfaAstrom.apio.
    return erfa.refco(
        observed_frame.pressure.to_value(u.hPa),
        observed_frame.temperature.to_value(u.deg_C),
        observed_frame.relative_humidity.value,
        observed_frame.obswl.to_value(u.micron),
    )


def _apply_refraction_alt(alt, refa, refb):
    """Apply refraction, transforming true altitude -> observed altitude.

    Parameters
    ----------
    alt : ndarray
        True altitude [radian].
    refa, refb : ndarray
        Refraction coefficients [radian].

    Returns
    -------
    alt_obs : ndarray
        Observed (refracted) altitude [radian].
    """
    zd = PIOVER2 - alt
    t = np.tan(zd)
    # ERFA/sofa-style two-constant model: R = A*tan(z) + B*tan(z)^3.
    zd_obs = zd - (refa * t + refb * t**3)
    return PIOVER2 - zd_obs


def _remove_refraction_alt(alt_obs, refa, refb, *, niter=3):
    """Remove refraction, transforming observed altitude -> true altitude."""
    zd_obs = PIOVER2 - alt_obs
    # Fixed-point iteration for: zd_obs = zd - f(zd)
    zd = zd_obs
    for _ in range(niter):
        t = np.tan(zd)
        zd = zd_obs + (refa * t + refb * t**3)
    return PIOVER2 - zd


def _is_unitspherical(coord):
    # By convention in Astropy, either a UnitSphericalRepresentation or
    # a cartesian representation with dimensionless units indicates a
    # direction-like coordinate.
    return (
        isinstance(coord.data, UnitSphericalRepresentation)
        or coord.cartesian.x.unit == u.one
    )


def _topocentric_itrs_cartesian(itrs_coo, location, obstime):
    """ITRS cartesian representation of the vector from observer to target."""
    if _is_unitspherical(itrs_coo):
        return itrs_coo.cartesian

    obs_itrs = location.get_itrs(obstime=obstime)
    return itrs_coo.cartesian - obs_itrs.cartesian


def _geocentric_itrs_cartesian(topocentric_itrs_cart, location, obstime):
    """Geocentric ITRS cartesian representation of the target."""
    if topocentric_itrs_cart.x.unit == u.one:
        return topocentric_itrs_cart

    obs_itrs = location.get_itrs(obstime=obstime)
    return topocentric_itrs_cart + obs_itrs.cartesian


def _observed_cartesian_to_altaz_cartesian(observed_coo):
    """Convert AltAz/HADec cartesian to AltAz cartesian at same location."""
    if isinstance(observed_coo, AltAz):
        return observed_coo.cartesian

    # HADec -> AltAz using only Earth-fixed rotations.
    itrs_to_altaz = _itrs_to_altaz_mat(observed_coo.location)
    itrs_to_hadec = _itrs_to_hadec_mat(observed_coo.location)
    altaz_from_hadec = itrs_to_altaz @ matrix_transpose(itrs_to_hadec)
    return observed_coo.cartesian.transform(altaz_from_hadec)


def _altaz_cartesian_to_observed_cartesian(altaz_cart, observed_frame):
    """Convert AltAz cartesian to the requested observed frame cartesian."""
    if isinstance(observed_frame, AltAz):
        return altaz_cart

    itrs_to_altaz = _itrs_to_altaz_mat(observed_frame.location)
    itrs_to_hadec = _itrs_to_hadec_mat(observed_frame.location)
    hadec_from_altaz = itrs_to_hadec @ matrix_transpose(itrs_to_altaz)
    return altaz_cart.transform(hadec_from_altaz)


def _refract_in_altaz(altaz_cart, observed_frame, *, inverse=False):
    """Apply or remove refraction in an AltAz cartesian representation."""
    # No refraction if pressure is effectively zero.  (erfa.refco would also
    # yield refa=refb=0, but this avoids tan() work.)
    if np.all(observed_frame.pressure.to_value(u.hPa) == 0.0):
        return altaz_cart

    refa, refb = _refraction_constants(observed_frame)

    sph = (
        UnitSphericalRepresentation.from_cartesian(altaz_cart)
        if altaz_cart.x.unit == u.one
        else SphericalRepresentation.from_cartesian(altaz_cart)
    )

    az = sph.lon.to_value(u.radian)
    alt = sph.lat.to_value(u.radian)

    if inverse:
        alt = _remove_refraction_alt(alt, refa, refb)
    else:
        alt = _apply_refraction_alt(alt, refa, refb)

    alt_q = u.Quantity(alt, u.radian, copy=False)
    az_q = u.Quantity(az, u.radian, copy=False)

    if isinstance(sph, UnitSphericalRepresentation):
        new_sph = UnitSphericalRepresentation(lon=az_q, lat=alt_q, copy=False)
    else:
        new_sph = SphericalRepresentation(
            lon=az_q, lat=alt_q, distance=sph.distance, copy=False
        )

    return new_sph.to_cartesian()


@frame_transform_graph.transform(FunctionTransformWithFiniteDifference, ITRS, AltAz)
@frame_transform_graph.transform(FunctionTransformWithFiniteDifference, ITRS, HADec)
def itrs_to_observed(itrs_coo, observed_frame):
    """Direct ITRS -> observed transform staying within ITRS."""
    # Form the topocentric ITRS position.
    topo_itrs = _topocentric_itrs_cartesian(
        itrs_coo, observed_frame.location, observed_frame.obstime
    )

    # Work in AltAz to apply/refuse refraction (a purely zenith-direction
    # correction).
    altaz_cart = topo_itrs.transform(_itrs_to_altaz_mat(observed_frame.location))
    altaz_cart = _refract_in_altaz(altaz_cart, observed_frame, inverse=False)

    # Convert to requested observed frame and return in spherical form.
    obs_cart = _altaz_cartesian_to_observed_cartesian(altaz_cart, observed_frame)

    if _is_unitspherical(itrs_coo):
        rep = UnitSphericalRepresentation.from_cartesian(obs_cart)
    else:
        rep = SphericalRepresentation.from_cartesian(obs_cart)

    return observed_frame.realize_frame(rep)


@frame_transform_graph.transform(FunctionTransformWithFiniteDifference, AltAz, ITRS)
@frame_transform_graph.transform(FunctionTransformWithFiniteDifference, HADec, ITRS)
def observed_to_itrs(observed_coo, itrs_frame):
    """Direct observed -> ITRS transform staying within ITRS."""
    # Convert input to AltAz axes (Earth-fixed), then remove refraction.
    altaz_cart = _observed_cartesian_to_altaz_cartesian(observed_coo)
    altaz_cart = _refract_in_altaz(altaz_cart, observed_coo, inverse=True)

    # Convert to topocentric ITRS.
    topo_itrs = altaz_cart.transform(
        matrix_transpose(_itrs_to_altaz_mat(observed_coo.location))
    )

    # Add observer's geocentric ITRS position.
    geo_itrs = _geocentric_itrs_cartesian(
        topo_itrs, observed_coo.location, observed_coo.obstime
    )

    return itrs_frame.realize_frame(geo_itrs)
